    [Hookable(false)]
    public static GUPVendPriceGroup find(GUPVendPriceGroupId _vendPriceGroupId, boolean _forUpdate = false)
    {
        GUPVendPriceGroup vendPriceGroup;
        
        vendPriceGroup.selectForUpdate(_forUpdate);

        if (_vendPriceGroupId)
        {
            select firstOnly vendPriceGroup
                where vendPriceGroup.VendPriceGroupId == _vendPriceGroupId;
        }
    
        return vendPriceGroup;
    }

    static boolean exist(GUPVendPriceGroupId _vendPricegroupId, boolean _silent = true)
    {
        if (_vendPricegroupId)
        {
            GUPVendPriceGroup vendPriceGroup;

            select firstonly RecId from vendPriceGroup
                index hint GroupIdx
                where vendPriceGroup.VendPriceGroupId == _vendPricegroupId;

            if (! _silent && ! vendPriceGroup)
            {
                return checkFailed(strFmt("@SYS14690", _vendPricegroupId));
            }
            else
            {
                return vendPriceGroup.RecId != 0;
            }
        }

        return false;
    }

    public static void vendPriceGroupIdLookup(FormControl _callingControl)
    {
        Query                query = new Query();
        QueryBuildDataSource qbds;
        SysTableLookup       sysTableLookup = SysTableLookup::newParameters(tableNum(GUPVendPriceGroup), _callingControl);

        sysTableLookup.addLookupfield(fieldNum(GUPVendPriceGroup, VendPriceGroupId));
        sysTableLookup.addLookupfield(fieldNum(GUPVendPriceGroup, Description));

        qbds = query.addDataSource(tableNum(GUPVendPriceGroup));
     
        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();
    }
